<template><div class="page-content"><div class="content-title"><div><h1>订单审核中心</h1><p>统一处理积分兑换、人工定制与上岸权益订单</p></div><button class="outline-btn" @click="$emit('toast','游客名单已导出')">⇩ 导出游客名单</button></div><div class="order-tabs"><button v-for="(t,i) in tabs" :class="{active:tab===i}" @click="tab=i">{{t}} <span>{{counts[i]}}</span></button></div><div class="order-list"><article v-for="o in filtered" :key="o.id"><div class="order-title"><label><input type="checkbox" v-model="o.checked"></label><div><span class="order-type" :class="o.type==='积分兑换'?'orange':'green'">{{o.type}}</span><b>{{o.title}}</b><small>{{o.orderNo}} · {{o.time}}</small></div><em :class="['order-status','s'+o.status]">{{['待审核','已通过','已驳回'][o.status]}}</em></div><div class="order-detail"><div><span>申请人</span><b>{{o.user}}</b></div><div><span>联系电话</span><b>{{o.phone}}</b></div><div><span>出行日期</span><b>{{o.date}}</b></div><div><span>合作旅行社</span><b>{{o.agency||'待分配'}}</b></div><div><span>订单积分</span><b>{{o.amount}}</b></div></div><div class="order-foot"><button @click="$emit('toast','订单详情已展开')">查看详情</button><button @click="$emit('toast','旅行社分配窗口已打开')">分配旅行社</button><template v-if="o.status===0"><button class="reject" @click="review(o,2)">驳回</button><button class="approve" @click="review(o,1)">审核通过</button></template></div></article></div><div v-if="!filtered.length" class="empty-state">这个分类暂时没有订单</div></div></template>
<script setup>import{computed,onMounted,ref}from'vue';import{api}from'../services/api';const emit=defineEmits(['toast']);const tab=ref(0),tabs=['待审核','已通过','已驳回'];const fallback=[{id:1,orderNo:'TS20260621008',title:'泰山经典游 2 天 1 夜',type:'积分兑换',time:'06-21 14:32',user:'林晓雨',phone:'176****8032',date:'2026-07-06',agency:'齐鲁文旅',amount:'100 积分',status:0},{id:2,orderNo:'DZ20260621016',title:'川西雪山深度定制',type:'人工定制',time:'06-21 13:08',user:'陈泽宇',phone:'139****2177',date:'2026-08-12',agency:'',amount:'7680 积分',status:0}];const orders=ref(fallback);const filtered=computed(()=>orders.value.filter(o=>o.status===tab.value));const counts=computed(()=>[0,1,2].map(s=>orders.value.filter(o=>o.status===s).length));const mapOrder=o=>({id:o.id,orderNo:o.order_no,title:o.title,type:o.order_type,time:new Date(o.created_at).toLocaleString(),user:o.user_name,phone:o.phone,date:o.travel_date,agency:o.agency,amount:o.amount_text,status:o.status});const review=async(o,status)=>{try{const saved=await api.reviewOrder(o.id,{status,reject_reason:status===2?'运营后台驳回':''});Object.assign(o,mapOrder(saved));emit('toast',status===1?'订单已通过':'订单已驳回')}catch{o.status=status;emit('toast','后端未连接，审核状态仅本地更新')}};onMounted(async()=>{try{orders.value=(await api.getOrders()).map(mapOrder)}catch{}})</script>
